import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';
import { fileURLToPath, URL } from 'node:url';

const r = (p: string) => fileURLToPath(new URL(p, import.meta.url));

// https://vitejs.dev/config/
export default defineConfig({
  plugins: [react()],
  resolve: {
    alias: {
      '@': fileURLToPath(new URL('./src', import.meta.url)),
    },
  },
  optimizeDeps: {
    exclude: ['lucide-react'],
  },
  build: {
    rollupOptions: {
      // Prerendered public routes (generated by scripts/generate_seo_html.py and committed).
      // Each is a full HTML entry that boots the same app, so a plain `vite build` ships
      // crawlable HTML with correct hashed asset URLs. Served at /<route>/ by the host.
      input: {
        main: r('./index.html'),
        app: r('./app.html'), // app shell for signed-in routes (see public/_redirects)
        catalog: r('./catalog/index.html'),
        paths: r('./paths/index.html'),
        upgrade: r('./upgrade/index.html'),
        request: r('./request/index.html'),
        book: r('./book/index.html'),
      },
    },
  },
});
